var rows = root.querySelectorAll('.trm0-quote-grid-bd .trm0-quote-grid-r');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var st = [];
for (var i = 0; i < rows.length; i++){
  st.push({ b: parseFloat(rows[i].getAttribute('data-b')), l: parseFloat(rows[i].getAttribute('data-l')) });
}
function fmt(n){
  var s = n.toFixed(2).split('.');
  s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return s.join('.');
}
function paint(i, dir){
  var r = rows[i], s = st[i];
  var chg = s.l - s.b, pc = (chg / s.b) * 100;
  var up = chg >= 0;
  var cg = r.querySelector('.trm0-quote-grid-cg');
  var pcE = r.querySelector('.trm0-quote-grid-pc');
  r.querySelector('.trm0-quote-grid-px').textContent = fmt(s.l);
  cg.textContent = (up ? '+' : '') + fmt(chg);
  pcE.textContent = (up ? '+' : '') + pc.toFixed(2);
  cg.className = 'trm0-quote-grid-cg ' + (up ? 'trm0-quote-grid-up' : 'trm0-quote-grid-dn');
  pcE.className = 'trm0-quote-grid-pc ' + (up ? 'trm0-quote-grid-up' : 'trm0-quote-grid-dn');
  if (reduce || !dir) return;
  r.classList.remove('trm0-quote-grid-fu', 'trm0-quote-grid-fd');
  void r.offsetWidth;
  r.classList.add(dir > 0 ? 'trm0-quote-grid-fu' : 'trm0-quote-grid-fd');
}
for (var k = 0; k < rows.length; k++) paint(k, 0);
if (!reduce){
  setInterval(function(){
    var i = Math.floor(Math.random() * st.length);
    var s = st[i];
    var step = s.b * (Math.random() * 0.0016 + 0.0002);
    var dir = Math.random() > 0.48 ? 1 : -1;
    s.l = Math.round((s.l + step * dir) * 100) / 100;
    paint(i, dir);
  }, 620);
}

