var vals = root.querySelectorAll('.trm0-secdes-v');
var pxE = root.querySelector('.trm0-secdes-px');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var pool = 'ABCDEFGHJKLMNPQRSTUVWXYZ0123456789';
function scramble(el, delay){
  var fin = el.getAttribute('data-v') || '';
  if (reduce){ el.textContent = fin; return; }
  el.textContent = '';
  setTimeout(function(){
    var f = 0;
    var t = setInterval(function(){
      f++;
      if (f > 5){ clearInterval(t); el.textContent = fin; return; }
      var s = '';
      for (var i = 0; i < fin.length; i++){
        s += fin.charAt(i) === ' ' ? ' ' : pool.charAt(Math.floor(Math.random() * pool.length));
      }
      el.textContent = s;
    }, 45);
  }, delay);
}
for (var i = 0; i < vals.length; i++) scramble(vals[i], 60 + i * 70);
var px = 168.44;
if (!reduce){
  setInterval(function(){
    px = Math.round((px + (Math.random() - 0.48) * 0.14) * 100) / 100;
    pxE.textContent = px.toFixed(2);
    pxE.classList.remove('trm0-secdes-fl');
    void pxE.offsetWidth;
    pxE.classList.add('trm0-secdes-fl');
  }, 1400);
}

